 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='verb-patterns' AND catalog_hash='e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' AND payload_md5='b3ea797586d01ee8f017200f61d0fee1' AND md5((payload->'quizItems')::text)='7f5be69bc5125a69f7e128be5d920846') THEN RAISE EXCEPTION 'Base archive or retained questions differ'; END IF;
