INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','verb-patterns','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"verb-patterns","title":"Verbs followed by -ing or to","level":"A2","order":37,"summary":"Choose the second verb’s form from the pattern required by the first verb.","learningGoals":["Verbs with -ing","Verbs with to","Preserve the pattern"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Verbs with -ing","explanation":"Enjoy, avoid, finish, practise and several other verbs take an -ing form when followed directly by another verb. Learn the pattern with the first verb.","examples":["We enjoy solving riddles.","I avoid wasting paper."]},{"title":"Verbs with to","explanation":"Want, hope, plan, decide and several other verbs take to plus the base form when followed directly by another verb.","examples":["We hope to arrive early.","I offered to wash up."]},{"title":"Preserve the pattern","explanation":"A question or negative does not change the complement pattern. Some verbs, including like and love, allow both forms and are excluded from single-answer contrasts here.","examples":["Do you enjoy solving riddles?","I do not want to leave yet."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-verb-patterns"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["When one verb follows another, the first verb often determines the second verb’s form. These patterns are lexical: a broad meaning such as liking or planning cannot predict every combination. Learn the verb with its complement and a short sentence."],"rules":[{"title":"Verbs with -ing","explanation":"Enjoy, avoid, finish, practise and several other verbs take an -ing form when followed directly by another verb. Learn the pattern with the first verb.","examples":["We enjoy solving riddles.","I avoid wasting paper.","They **decided to leave** early."],"pattern":"enjoy / avoid / finish + **-ing**","paragraphs":["Enjoy, avoid, finish and keep commonly take an -ing complement. The -ing form names the activity and does not itself mark present continuous. I enjoyed swimming is past simple for enjoyed, with an -ing complement naming what was enjoyed."],"id":"verb-patterns-foundation-1","domain":"nonfinite","referenceIds":["bc-verb-patterns"],"readingVersion":"foundations-2026-09-v2"},{"title":"Verbs with to","explanation":"Want, hope, plan, decide and several other verbs take to plus the base form when followed directly by another verb.","examples":["We hope to arrive early.","I offered to wash up.","She **avoids driving** at night."],"pattern":"want / decide / hope + **to + base verb**","paragraphs":["Want, decide, hope and plan commonly take a to-infinitive. The tense belongs on the first verb: she decided to leave. The second verb stays base after to. Some verbs require a person object as well, such as remind someone to call."],"id":"verb-patterns-foundation-2","domain":"nonfinite","referenceIds":["bc-verb-patterns"],"readingVersion":"foundations-2026-09-v2"},{"title":"Preserve the pattern","explanation":"A question or negative does not change the complement pattern. Some verbs, including like and love, allow both forms and are excluded from single-answer contrasts here.","examples":["Do you enjoy solving riddles?","I do not want to leave yet.","**Did** you **finish writing** the report?"],"pattern":"**Do** you enjoy **reading**?","paragraphs":["Questions and negatives change the first finite verb as needed but normally preserve the complement pattern: Does she enjoy reading? She doesn’t enjoy reading. Do-support does not turn every later verb into a bare infinitive."],"id":"verb-patterns-foundation-3","domain":"nonfinite","referenceIds":["bc-verb-patterns"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"Some verbs allow both patterns with similar meanings, such as like in many contexts. Others change meaning: remember to call is a duty, while remember calling is a memory. Prepositions take -ing, including prepositional to in look forward to meeting. The following chapters separate those contrasts.","examples":["They **decided to leave** early.","She **avoids driving** at night.","**Did** you **finish writing** the report?"],"id":"verb-patterns-foundation-4","domain":"nonfinite","referenceIds":["bc-verb-patterns"],"readingVersion":"foundations-2026-09-v2"},{"domain":"nonfinite","id":"control-understood-subjects","title":"Who does the action in an infinitive?","explanation":"An infinitive often has an understood subject supplied by the main clause. Different verbs assign that role differently. With promise to do something, the promiser normally does it; with persuade someone to do something, the person persuaded does it. Some constructions instead express a general or contextually supplied actor.","pattern":"She **promised to leave** / She **persuaded him to leave**","examples":["Maya **promised to help**: Maya would help.","Maya **persuaded Leo to help**: Leo would help."],"commonMistakes":["The noun nearest the infinitive is not always its understood subject. Read the main verb’s construction and meaning rather than applying a proximity shortcut."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"nonfinite","id":"raising-seem-appear","title":"Seem, appear and raising constructions","explanation":"In she seems to know, the main subject belongs semantically with the infinitive: she knows. The sentence can often be paraphrased with it seems that. This differs from a verb such as promise, whose subject also participates in the main event. Passive and perfect infinitives can occur after seem and appear.","pattern":"She **seems to know** / It **seems that she knows**.","examples":["There **seems to be** a mistake.","He **appears to have left**."],"commonMistakes":["There seems to be is possible because seems need not assign an action role to its subject. There promises to leave does not have the same ordinary structure."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"nonfinite","id":"bare-infinitives-perception-causation","title":"Bare infinitives after modals, let, make and perception verbs","explanation":"Central modals take a bare infinitive. Let and causative make normally do too; help allows forms with or without to. Perception verbs can take an object plus bare infinitive for an event viewed as a whole, or an -ing clause for an event viewed in progress. Passive make commonly restores to.","pattern":"They **made him wait**. / He **was made to wait**.","examples":["I saw her **cross** the road.","I saw her **crossing** the road."],"commonMistakes":["The perception contrast is about how the event is presented, not a guarantee of actual completion in every imaginable context. Causative let is normally replaced by be allowed to in a passive."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["enjoy / avoid / finish + **-ing**","want / decide / hope + **to + base verb**","**Do** you enjoy **reading**?"],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["infinitive-of-purpose"],"readingReferenceIds":["bc-verb-patterns","cambridge-nonfinite-scope","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='verb-patterns'
